ISL_101_LABEL_TO_ID: Dict[str, int] = {item["sign"].lower(): i for i, item in enumerate(PLAYLIST_101_CLASSES)}
ISL_101_ID_TO_LABEL: Dict[int, str] = {i: item["sign"] for i, item in enumerate(PLAYLIST_101_CLASSES)}

ISL_101_METADATA: Dict[str, Dict[str, Any]] = {
    item["sign"].lower(): {
        "sign": item["sign"],
        "display": item["display"],
        "lesson": item["lesson"],
        "lesson_title": item["lesson_title"],
        "category": item["category"],
        "hi": item["hi"],
        "meaning": item["meaning"],
    }
    for item in PLAYLIST_101_CLASSES
}

def get_playlist_sign_metadata(sign_key: str) -> Dict[str, Any]:
    """Retrieves full lesson and bilingual metadata for a playlist sign."""
    k = sign_key.lower().replace(" ", "_").replace("-", "_")
    if k in ISL_101_METADATA:
        return ISL_101_METADATA[k]
    # Check without underscores
    k2 = k.replace("_", "")
    for key, val in ISL_101_METADATA.items():
        if key.replace("_", "") == k2:
            return val
    return {
        "sign": sign_key.upper(),
        "display": sign_key.title(),
        "lesson": 0,
        "lesson_title": "General ISL",
        "category": "general",
        "hi": sign_key.title(),
        "meaning": f"Indian Sign Language gesture for {sign_key}",
    }

def get_signs_by_lesson(lesson_num: int) -> List[Dict[str, Any]]:
    """Returns all signs taught in a specific playlist lesson."""
    return [c for c in PLAYLIST_101_CLASSES if c["lesson"] == lesson_num]
